---
import type { AlertProps as BaseAlertProps } from "@pisagor/props";
import type { AlertRecipeSlot } from "@pisagor/recipes";
import type { HTMLAttributes } from "astro/types";
import type { VariantClassNames } from "../../internal/types";
import AlertAction from "./alert-action.astro";
import AlertDescription from "./alert-description.astro";
import AlertRoot from "./alert-root.astro";
import AlertTitle from "./alert-title.astro";

interface Props extends Omit<HTMLAttributes<"div">, "title">, BaseAlertProps {
  /** Bold title line. */
  title?: string;
  /** Description content. */
  description?: string;
  /** Slot class names */
  classNames?: VariantClassNames<AlertRecipeSlot>;
}

const { title, description, classNames, ...rest } = Astro.props;
const hasIcon = Astro.slots.has("icon");
const hasAction = Astro.slots.has("action");
const hasTitle = Astro.slots.has("title") || title !== undefined;
const hasDescription =
  Astro.slots.has("description") || description !== undefined;
---

<AlertRoot {...rest}>
  {hasIcon && <slot name="icon" />}
  {hasTitle && (
    <AlertTitle class={classNames?.title}>
      {title ?? <slot name="title" />}
    </AlertTitle>
  )}
  {hasDescription && (
    <AlertDescription class={classNames?.description}>
      {description ?? <slot name="description" />}
    </AlertDescription>
  )}
  {hasAction && (
    <AlertAction class={classNames?.action}>
      <slot name="action" />
    </AlertAction>
  )}
</AlertRoot>

import { alertRecipe } from "@pisagor/recipes";
import { createSlotRecipeContext } from "../../internal/create-slot-recipe-context";

export const { withContext, withProvider } = createSlotRecipeContext({
  name: "Alert",
  recipe: alertRecipe,
});

---
import type { HTMLAttributes } from "astro/types";
import { withContext } from "./alert.context";

type Props = HTMLAttributes<"div">;

const action = withContext(Astro.props, { name: "Action" });
---

<div {...action.props}>
  <slot />
</div>

