---
import type { AnnouncementProps as BaseAnnouncementProps } from "@pisagor/props";
import type { HTMLAttributes } from "astro/types";
import AnnouncementRoot from "./announcement-root.astro";
import AnnouncementTitle from "./announcement-title.astro";

interface Props
  extends Omit<HTMLAttributes<"div">, "title">,
    BaseAnnouncementProps {
  /**
   * The ARIA role of the announcement.
   *
   * @defaultValue "status"
   */
  role?: "status" | "alert";
  /** Title content rendered inside `Announcement.Title`. */
  title?: string;
}

const { title, ...rest } = Astro.props;
const hasBadge = Astro.slots.has("badge");
const hasTitle = Astro.slots.has("title") || title !== undefined;
---

<AnnouncementRoot {...rest}>
  {hasBadge && <slot name="badge" />}
  {hasTitle && (
    <AnnouncementTitle>{title ?? <slot name="title" />}</AnnouncementTitle>
  )}
  <slot />
</AnnouncementRoot>

import { announcementRecipe } from "@pisagor/recipes";
import { createSlotRecipeContext } from "../../internal/create-slot-recipe-context";

export const { withContext, withProvider } = createSlotRecipeContext({
  name: "Announcement",
  recipe: announcementRecipe,
});

---
import type { AnnouncementProps as BaseAnnouncementProps } from "@pisagor/props";
import type { HTMLAttributes } from "astro/types";
import { withProvider } from "./announcement.context";

interface Props
  extends Omit<HTMLAttributes<"div">, "title">,
    BaseAnnouncementProps {
  /**
   * The ARIA role of the announcement.
   *
   * @defaultValue "status"
   */
  role?: "status" | "alert";
}

const root = withProvider(Astro.props, {
  defaultProps: { role: "status" },
  name: "Root",
  slot: "base",
});
---

<div {...root.props}>
  <slot />
</div>

---
import type { HTMLAttributes } from "astro/types";
import { withContext } from "./announcement.context";

type Props = HTMLAttributes<"span">;

const title = withContext(Astro.props, { name: "Title", slot: "title" });
---

<span {...title.props}>
  <slot />
</span>

import AnnouncementShorthand from "./announcement.astro";
import AnnouncementRoot from "./announcement-root.astro";
import AnnouncementTitle from "./announcement-title.astro";

export const Announcement = Object.assign(AnnouncementShorthand, {
  Root: AnnouncementRoot,
  Title: AnnouncementTitle,
});

---
import type { AspectRatioProps as BaseAspectRatioProps } from "@pisagor/props";
import { aspectRatioRecipe } from "@pisagor/recipes";
import type { HTMLAttributes } from "astro/types";

interface Props extends HTMLAttributes<"div">, BaseAspectRatioProps {
  /**
   * CSS aspect-ratio value applied via `--ratio`.
   *
   * @example "16/9"
   */
  ratio?: string | number;
}

const {
  ratio,
  style,
  recipe = aspectRatioRecipe,
  class: className,
  ...rest
} = Astro.props;

const mergedStyle =
  ratio === undefined
    ? style
    : [typeof style === "string" ? style : "", `--ratio:${ratio}`]
        .filter(Boolean)
        .join(";");
---

<div
  {...rest}
  class={recipe({ className })}
  data-part="root"
  data-scope="aspect-ratio"
  style={mergedStyle}
>
  <slot />
</div>

