---
import type { BreadcrumbProps as BaseBreadcrumbProps } from "@pisagor/props";
import type { HTMLAttributes } from "astro/types";
import BreadcrumbItem from "./breadcrumb-item.astro";
import BreadcrumbLink from "./breadcrumb-link.astro";
import BreadcrumbList from "./breadcrumb-list.astro";
import BreadcrumbPage from "./breadcrumb-page.astro";
import BreadcrumbRoot from "./breadcrumb-root.astro";
import BreadcrumbSeparator from "./breadcrumb-separator.astro";

interface BreadcrumbPresetItem {
  label: string;
  href?: string;
  isCurrentPage?: boolean;
}

interface Props extends HTMLAttributes<"nav">, BaseBreadcrumbProps {
  /**
   * Accessible label for the breadcrumb navigation landmark.
   *
   * @defaultValue "Breadcrumb"
   */
  "aria-label"?: string;
  items?: BreadcrumbPresetItem[];
}

const { items = [], ...rest } = Astro.props;
---

<BreadcrumbRoot {...rest}>
  {items.length > 0 && (
    <BreadcrumbList>
      {items.map((item, index) => (
        <>
          {index > 0 && <BreadcrumbSeparator />}
          <BreadcrumbItem>
            {item.isCurrentPage ? (
              <BreadcrumbPage>{item.label}</BreadcrumbPage>
            ) : item.href ? (
              <BreadcrumbLink href={item.href}>{item.label}</BreadcrumbLink>
            ) : (
              item.label
            )}
          </BreadcrumbItem>
        </>
      ))}
    </BreadcrumbList>
  )}
  <slot />
</BreadcrumbRoot>

import { breadcrumbItemRecipe, breadcrumbRecipe } from "@pisagor/recipes";
import { createSlotRecipeContext } from "../../internal/create-slot-recipe-context";

export const { useStyles: useBreadcrumb, withContext: withBreadcrumbContext } =
  createSlotRecipeContext({
    name: "Breadcrumb",
    recipe: breadcrumbRecipe,
  });

export const {
  withContext: withBreadcrumbItemContext,
  withProvider: withBreadcrumbItemProvider,
} = createSlotRecipeContext({
  name: "BreadcrumbItem",
  recipe: breadcrumbItemRecipe,
});

---
import type { BreadcrumbItemProps as BaseBreadcrumbItemProps } from "@pisagor/props";
import type { HTMLAttributes } from "astro/types";
import { withBreadcrumbItemProvider } from "./breadcrumb.context";

type Props = HTMLAttributes<"li"> & BaseBreadcrumbItemProps;

const item = withBreadcrumbItemProvider(Astro.props, {
  name: "Item",
  slot: "base",
});
---

<li {...item.props}>
  <slot />
</li>

---
import type { HTMLAttributes } from "astro/types";
import { withBreadcrumbItemContext } from "./breadcrumb.context";

type Props = HTMLAttributes<"a">;

const link = withBreadcrumbItemContext(Astro.props, { name: "Link" });
---

{/* biome-ignore lint/a11y/useAnchorContent: content is the default slot */}
{/* biome-ignore lint/a11y/useValidAnchor: href is forwarded from props */}
<a {...link.props}>
  <slot />
</a>

---
import type { HTMLAttributes } from "astro/types";
import { withBreadcrumbContext } from "./breadcrumb.context";

type Props = HTMLAttributes<"ol">;

const list = withBreadcrumbContext(Astro.props, {
  defaultProps: { role: "list" },
  name: "List",
});
---

<ol {...list.props}>
  <slot />
</ol>

---
import type { HTMLAttributes } from "astro/types";
import { withBreadcrumbItemContext } from "./breadcrumb.context";

type Props = HTMLAttributes<"span">;

const page = withBreadcrumbItemContext(Astro.props, {
  defaultProps: { "aria-current": "page" },
  name: "Page",
});
---

<span {...page.props}>
  <slot />
</span>

---
import type { BreadcrumbProps as BaseBreadcrumbProps } from "@pisagor/props";
import type { HTMLAttributes } from "astro/types";

interface Props extends HTMLAttributes<"nav">, BaseBreadcrumbProps {
  /**
   * Accessible label for the breadcrumb navigation landmark.
   *
   * @defaultValue "Breadcrumb"
   */
  "aria-label"?: string;
}

const {
  "aria-label": ariaLabel = "Breadcrumb",
  recipe: _recipe,
  ...rest
} = Astro.props;
---

<nav {...rest} aria-label={ariaLabel} data-part="root" data-scope="breadcrumb">
  <slot />
</nav>

---
import type { HTMLAttributes } from "astro/types";
import { useBreadcrumb } from "./breadcrumb.context";

type Props = HTMLAttributes<"li">;

const { class: className, ...rest } = Astro.props;
const { slots } = useBreadcrumb();
const hasDefault = Astro.slots.has("default");
---

<li
  {...rest}
  aria-hidden="true"
  class={slots.separator({ class: className })}
  data-part="separator"
  data-scope="breadcrumb"
  role="presentation"
>
  {hasDefault ? (
    <slot />
  ) : (
    <svg
      aria-hidden="true"
      fill="currentColor"
      height="1em"
      viewBox="0 0 256 256"
      width="1em"
      xmlns="http://www.w3.org/2000/svg"
    >
      <path d="M181.66,133.66l-80,80a8,8,0,0,1-11.32-11.32L164.69,128,90.34,53.66a8,8,0,0,1,11.32-11.32l80,80A8,8,0,0,1,181.66,133.66Z" />
    </svg>
  )}
</li>

import BreadcrumbShorthand from "./breadcrumb.astro";
import BreadcrumbEllipsis from "./breadcrumb-ellipsis.astro";
import BreadcrumbItem from "./breadcrumb-item.astro";
import BreadcrumbLink from "./breadcrumb-link.astro";
import BreadcrumbList from "./breadcrumb-list.astro";
import BreadcrumbPage from "./breadcrumb-page.astro";
import BreadcrumbRoot from "./breadcrumb-root.astro";
import BreadcrumbSeparator from "./breadcrumb-separator.astro";

export const Breadcrumb = Object.assign(BreadcrumbShorthand, {
  Ellipsis: BreadcrumbEllipsis,
  Item: BreadcrumbItem,
  Link: BreadcrumbLink,
  List: BreadcrumbList,
  Page: BreadcrumbPage,
  Root: BreadcrumbRoot,
  Separator: BreadcrumbSeparator,
});

