---
interface Props {
  /** Byte value to format. */
  value: number;
  /** BCP 47 locale. Defaults to the runtime default locale. */
  locale?: string;
  /** Unit display style for `Intl.NumberFormat`. */
  unitDisplay?: Intl.NumberFormatOptions["unitDisplay"];
}

const UNITS = [
  "byte",
  "kilobyte",
  "megabyte",
  "gigabyte",
  "terabyte",
  "petabyte",
] as const;

function formatBytes(
  value: number,
  locale: string | undefined,
  unitDisplay: Intl.NumberFormatOptions["unitDisplay"],
): string {
  let amount = value;
  let unitIndex = 0;

  while (Math.abs(amount) >= 1000 && unitIndex < UNITS.length - 1) {
    amount /= 1000;
    unitIndex += 1;
  }

  return new Intl.NumberFormat(locale, {
    maximumFractionDigits: 2,
    style: "unit",
    unit: UNITS[unitIndex],
    unitDisplay,
  }).format(amount);
}

const { value, locale, unitDisplay = "short" } = Astro.props;
const formatted = formatBytes(value, locale, unitDisplay);
---

{formatted}

---
interface Props {
  /** Number value to format. */
  value: number;
  /** BCP 47 locale. Defaults to the runtime default locale. */
  locale?: string;
  /** Extra options forwarded to `Intl.NumberFormat`. */
  options?: Intl.NumberFormatOptions;
}

const { value, locale, options } = Astro.props;
const formatted = new Intl.NumberFormat(locale, options).format(value);
---

{formatted}

---
interface Props {
  /** Target date for relative formatting. */
  value: Date | string | number;
  /** BCP 47 locale. Defaults to the runtime default locale. */
  locale?: string;
  /** Numeric style for `Intl.RelativeTimeFormat`. */
  numeric?: Intl.RelativeTimeFormatOptions["numeric"];
  /** Style for `Intl.RelativeTimeFormat`. */
  style?: Intl.RelativeTimeFormatOptions["style"];
}

const DIVISIONS: { amount: number; unit: Intl.RelativeTimeFormatUnit }[] = [
  { amount: 60, unit: "second" },
  { amount: 60, unit: "minute" },
  { amount: 24, unit: "hour" },
  { amount: 7, unit: "day" },
  { amount: 4.34524, unit: "week" },
  { amount: 12, unit: "month" },
  { amount: Number.POSITIVE_INFINITY, unit: "year" },
];

function formatRelativeTime(
  date: Date,
  locale: string | undefined,
  numeric: Intl.RelativeTimeFormatOptions["numeric"],
  style: Intl.RelativeTimeFormatOptions["style"],
): string {
  const formatter = new Intl.RelativeTimeFormat(locale, { numeric, style });
  let duration = (date.getTime() - Date.now()) / 1000;

  for (const division of DIVISIONS) {
    if (Math.abs(duration) < division.amount) {
      return formatter.format(Math.round(duration), division.unit);
    }

    duration /= division.amount;
  }

  return formatter.format(Math.round(duration), "year");
}

const { value, locale, numeric = "auto", style = "long" } = Astro.props;

const date = value instanceof Date ? value : new Date(value);
const formatted = formatRelativeTime(date, locale, numeric, style);
---

{formatted}

import FormatByte from "./format-byte.astro";
import FormatNumber from "./format-number.astro";
import FormatRelativeTime from "./format-relative-time.astro";

export { FormatByte, FormatNumber, FormatRelativeTime };

export const Format = {
  Byte: FormatByte,
  Number: FormatNumber,
  RelativeTime: FormatRelativeTime,
};

